<template><div class="app-container"><div class="filter-container"><el-select v-model="form.reportType" placeholder="报表类型"><el-option label="区域业绩" value="REGION"/><el-option label="库存库龄" value="INVENTORY_AGING"/><el-option label="财务对账" value="FINANCE"/><el-option label="匿名健康汇总" value="HEALTH_ANONYMOUS"/></el-select><el-date-picker v-model="dates" type="daterange" value-format="yyyy-MM-dd"/><el-button type="primary" @click="create">创建导出</el-button><el-button @click="run">立即处理待导出</el-button><el-button @click="load">刷新</el-button></div><el-table :data="list" border><el-table-column prop="taskNo" label="任务号" min-width="180"/><el-table-column prop="reportType" label="类型"/><el-table-column prop="status" label="状态"/><el-table-column prop="progress" label="进度"/><el-table-column prop="fileSize" label="文件大小"/><el-table-column prop="errorMessage" label="错误"/><el-table-column label="操作"><template slot-scope="s"><el-button v-if="s.row.status==='SUCCESS'" size="mini" @click="download(s.row)">下载</el-button></template></el-table-column></el-table></div></template><script>import{createJkReportExport,getJkReportExportList,runJkReportExports,downloadJkReportExport}from'@/api/jkBusiness';export default{data(){return{form:{reportType:'REGION'},dates:[],list:[]}},created(){this.load()},methods:{data(r){return(r&&r.data&&r.data.list)||(r&&r.data)||(r&&r.list)||r||[]},load(){getJkReportExportList({page:1,limit:100}).then(r=>this.list=this.data(r))},create(){createJkReportExport({...this.form,startDate:this.dates&&this.dates[0],endDate:this.dates&&this.dates[1]}).then(()=>{this.$message.success('任务已创建');this.load()})},run(){runJkReportExports().then(()=>{this.$message.success('已执行');this.load()})},download(row){downloadJkReportExport(row.id).then(res=>{const blob=res instanceof Blob?res:new Blob([res]);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=row.fileName||'report.csv';a.click();URL.revokeObjectURL(url)})}}}</script>
